graphql.query:
query ImportCompany($id: uuid!) {
  companyByPk(id: $id) {
    id
    businessEntity { id }
    officialName
    businessName
    description
    websiteUrl
    webshopUrl
    logoUrl
    logoThumbnailUrl
    socialMediaLinks { linkType url }
    contactDetails(limit: 1) { email phone }
    postalAddresses(limit: 1) {
      streetName
      city
      postalCode
      location
    }
    products {
      id
      type
      accessible
      externalSource
      urlPrimary
      webshopUrlPrimary
      productInformations { language name description url webshopUrl }
      productPricings { fromPrice toPrice pricingUnit }
      productDuration { days hours minutes }
      productCapacities { min max }
      productImages {
        largeUrl
        thumbnailUrl
        originalUrl
        altText
        copyright
        coverPhoto
        orientation
        orderIndex
      }
      productTags { tag }
      productTargetGroups { targetGroupId }
      productCertificates { certificate certificateDetails { name description logoUrl websiteUrl } }
      productAvailabilities {
        startDate
        endDate
        startTime
        endTime
        doorsOpenAt
        nroOfTickets
      }
      productAvailableMonths { month }
      postalAddresses(limit: 1) {
        streetName
        city
        postalCode
        location
      }
    }
  }
}
